add('digital-multimeter','17.3','102–103','拓展探究','用数字多用表测量电阻','circuit','multimeter','学习在断电条件下直接测量电阻。','数字多用表|断电电阻|小灯泡','检查表笔插孔和电阻挡。|使被测元件脱离带电电路。|选择合适量程并读取单位。','低温灯丝阻值通常小于发光时的U/I。','欧姆挡测量需要断电；显示单位和量程决定读数含义。','千欧与欧姆需换算|表内电源参与欧姆挡测量','不得用电阻挡测量通电电路','显示1.25 kΩ，写成欧姆是多少？','1.25 kΩ=1250 Ω。',('表盘显示1.25 kΩ。','1 kΩ=1000 Ω。','R=1.25×1000=1250 Ω。','电阻为1250 Ω。'),safety='仅测断电并放电后的低压元件；不要使用未知档位接触市电。')
add('lamp-power','18.2','115–116','演示实验','测量小灯泡电功率并比较亮度','circuit','lamp-power','用灯泡两端电压和通过电流确定实际功率。','额定2.5 V小灯泡|电流表|电压表|变阻器|电源','从低电压开始调节。|测量额定及低于额定状态的U、I。|计算P并与亮度比较。','实际功率较大时通常较亮；额定电压下对应额定功率。','实际电功率P=UI，亮度主要反映灯泡的实际功率。','测额定功率需把电压调到额定值|不同状态功率不能平均求额定值','不能认为灯泡在任何电压下都以铭牌功率工作','灯泡2.5 V时电流0.30 A，额定功率多少？','额定功率0.75 W。',('U额=2.5 V，正常发光时I=0.30 A。','P=UI。','P额=2.5×0.30=0.75 W。','额定功率0.75 W。'),safety='模拟可比较过压；真实操作不长期超过额定电压。')
add('home-energy-audit','18.3','118–119','拓展探究','为家庭节约用电提出方案','household','energy-audit','用功率和使用时间估算电能并比较节电方案。','电器铭牌数据|使用时间表|电能表读数模型','统计电器功率和每日工作时间。|换算千瓦与小时后计算耗电量。|比较减少待机和缩短使用时间的方案。','高功率电器未必每日耗电最多，还要看工作时间。','电能W=Pt，节电方案应结合功率、使用时长和实际需求。','kW·h是电能单位，kW是功率单位','不要把能效等级与实际总耗电量混为一谈','20 W灯每天少开2 h，30天节约多少电？','节电1.2 kW·h。',('P=20 W=0.020 kW，减少时间2×30=60 h。','W=Pt。','W=0.020×60=1.2 kW·h。','一个月约节约1.2 kW·h。'),safety='只读铭牌和安全显示屏，不拆开电器或配电箱。')
add('joule-resistance','18.4','120','演示实验','比较电阻大小对电热的影响','joule','resistance','控制电流与时间，比较不同电阻的发热。','两段不同电阻丝|密闭空气盒|U形管|低压电源','把两段电阻丝串联以保持电流相同。|通电相同时间。|比较U形管液面差。','阻值较大的电阻丝使相应空气温升更明显。','电流和通电时间相同时，产生的电热与电阻成正比。','串联用于控制电流相同|液面差是温度变化的间接指示','电热与电阻正比的前提是电流不变','0.5 A通过10 Ω电阻20 s，放热多少？','产生50 J热量。',('I=0.5 A，R=10 Ω，t=20 s。','Q=I²Rt。','Q=0.5²×10×20=50 J。','电阻产生50 J热量。'),safety='防止电阻丝过热；只用教师配置的限流装置。')
add('joule-current','18.4','121','演示实验','比较电流大小对电热的影响','joule','current','保持电阻与时间相同，比较不同电流的发热。','相同电阻丝|分流电阻|U形管|低压电源','用分流电路改变其中一段电阻丝的电流。|保持两段电阻相同。|通电相同时间后比较温升指示。','电流较大的电阻丝产生的电热更多。','电阻和时间相同时，电热与电流的平方成正比。','平方关系：电流加倍、电热变为四倍','不要误说电热与电流一次方成正比','电流从0.2 A增至0.4 A，其他条件相同，电热变成几倍？','电热变成4倍。',('I₂/I₁=0.4/0.2=2，R、t不变。','Q₂/Q₁=(I₂/I₁)²。','Q₂/Q₁=2²=4。','电热变为原来的4倍。'))
