add('fuse-comparison','19.2','134–135','演示实验','比较保险丝与铜丝的过流表现','household','fuse','理解过流保护器件的作用与材料要求。','保险丝模型|铜丝模型|限流电路|电流读数','在模拟中缓慢增大电流。|比较不同材料的发热和熔断状态。|说明熔断对电路的作用。','合适的保险丝在过流后熔断，切断电路。','保险丝利用电流热效应保护电路，不能用普通铜丝替代。','过流可能来自总功率过大或短路|保护装置应与线路匹配','不是保险丝越粗越好','用铜丝代替保险丝为什么危险？','铜丝可能在危险电流下仍不断开，使导线或电器持续过热。',safety='仅仿真；不能在家制造过流，不得改装保险装置。')
add('home-circuit-design','19.3','141–144','拓展探究','设计家庭电路的分支与保护','household','design','根据用电负荷和安全要求设计家庭电路示意图。','家庭平面图|电器功率表|分支回路模型|保护接地模型','调查主要用电负荷。|将照明与大功率负荷合理分支。|检查开关、保护接地和过流保护位置。','同一电源下总功率增大时，总电流增加。','家庭用电器通常并联；保护器件、导线与负荷需匹配。','开关接在相线与用电器之间|保护地线不同于中性线','设计示意图不等于具备实际施工资格','总功率2200 W、供电220 V，工作电流约多少？','电流约10 A，实际器件选型还需由专业人员核定。',('总功率2200 W，电压220 V，按纯电阻近似。','I=P/U。','I=2200/220=10 A。','工作电流约10 A；不能只凭这一计算自行选线施工。'),safety='仅进行图纸与仿真设计；家庭电路施工必须由合格电工完成。')
add('magnetic-poles','20.1','147','小实验','观察磁体吸铁与磁极相互作用','magnet','poles','比较磁极与非磁极处的吸引，并判断两极作用。','条形磁体|小磁针|铁屑模型','比较磁体不同位置的吸引效果。|让两个N极相对，再让N、S相对。|观察吸引或排斥。','磁极附近磁作用较强；同名磁极排斥、异名吸引。','磁体有两个磁极，磁极间存在相互作用。','磁体不是吸引所有金属|磁极不可只凭吸引铁判断南北','不要将吸引铁屑误称为异名磁极吸引','磁铁能否吸引所有金属？','不能。铁、钴、镍等及某些合金容易被吸引，铜铝通常不会明显被普通磁体吸引。',safety='强磁体远离医疗植入设备和磁性存储器；防止夹手。')
add('compass-field','20.1','148','演示实验','用小磁针判断某点磁场方向','magnet','compass','把静止小磁针N极指向作为磁场方向。','条形磁体|多个小磁针','选定磁体附近一个位置。|先后放入不同小磁针。|记录其静止N极指向。','同一点处不同小磁针的N极指向一致。','某点磁场方向规定为小磁针静止时N极所指方向。','磁针受到磁场作用，磁场并非只有放入磁针才存在','不能把S极指向当作规定方向','换一枚小磁针，某点的磁场方向是否改变？','在小磁针不明显扰动原磁场的近似下，不改变。')
add('magnetic-field-map','20.1','149','学生实验','用磁针与铁屑描绘磁场分布','magnet','field-map','将分散位置的方向信息连成磁场分布图。','条形与蹄形磁体|透明板|铁屑|小磁针','在磁体周围不同位置放磁针并标记N极方向。|轻撒铁屑并轻敲透明板。|对比两种磁体的分布。','铁屑排列呈曲线状，不同位置磁针方向不同。','磁感线是描述磁场的模型，磁体外部方向从N极指向S极。','磁感线并非真实存在的线|线密反映相对强弱','铁屑只显示形状，方向还要靠磁针判断','为什么不能只靠铁屑判断磁场方向？','铁屑排列显示分布形态，却不标明N到S的箭头方向。',safety='铁屑不直接用手揉搓，避免进入眼睛。')
add('oersted','20.2','152–153','小实验','奥斯特实验：通电导线使磁针偏转','magnet','oersted','通过通断电和换向建立电流与磁场的联系。','小磁针|直导线|低压电源|开关','让直导线平行放在小磁针上方。|短时通电观察偏转。|断电后调换电源方向再观察。','通电时磁针偏转；电流反向后偏转方向改变。','电流周围存在磁场，磁场方向与电流方向有关。','导线位置和方向影响观察效果|通断电形成对照','不要把磁针偏转解释为导线的机械碰撞','反向通电的实验说明什么？','说明通电导线产生的磁场方向随电流方向改变。',safety='实际实验需要限流并短时通电，不能直接短接干电池。')
add('solenoid-field','20.2','153–154','学生实验','探究通电螺线管外部磁场方向','magnet','solenoid','通过小磁针判断螺线管磁极与电流方向关系。','螺线管|小磁针|低压电源|开关','记录绕线方向和电流方向。|在螺线管周围多点放置磁针。|反向通电后重新记录。','外部磁场形状类似条形磁体；反向通电后两极交换。','用安培定则可判断通电螺线管的N极。','四指弯向是电流绕向，大拇指指N极','不要把电子移动方向当作电流方向','只改变电流方向，螺线管磁极怎样变化？','N、S极交换。')
add('electromagnet-crane','20.3','158','小实验','制作电磁起重机并比较磁性强弱','magnet','electromagnet','比较电流、匝数和铁芯对电磁铁的影响。','绕线铁钉模型|低压电源|变阻器|曲别针','固定匝数，改变电流比较吸起能力。|固定电流，改变线圈匝数。|比较有铁芯与无铁芯的情形。','其他条件相同时，电流或匝数增大通常使磁性增强；铁芯可增强磁场。','电磁铁的通断、强弱和极性均可控制。','改变匝数同时可能改变电流，需控制变量','曲别针数量是相对指示，不是通用磁场单位','比较匝数影响时为何要保持电流相同？','否则磁性差异同时含电流和匝数两个因素，不能单独归因匝数。',safety='线圈会发热，使用绝缘导线和限流低压电源。')
add('electromagnetic-relay','20.3','159','小实验','观察电磁继电器的控制过程','magnet','relay','区分控制电路和工作电路的作用。','继电器剖面模型|低压控制电源|灯泡负载模型','辨认线圈、衔铁、弹簧和触点。|接通控制电路观察衔铁与触点。|断开控制电路观察恢复。','线圈通电吸引衔铁，使触点改变工作电路通断。','继电器利用电磁铁，以控制电路操纵另一工作电路。','两个电路功能不同，不能混画连接|触点状态需依据图判断','不要认为控制电流必然流过工作负载','控制线圈断电后触点为什么恢复？','电磁吸引作用减弱，弹簧使衔铁返回原位。',safety='只用低压负载模型；不将真实家庭电器接入自制继电器。')
add('magnetic-force-wire','20.4','161–162','演示实验','通电导体在磁场中受力','magnet','wire-force','比较电流方向和磁场方向对受力方向的影响。','蹄形磁体|导体棒|低压电源|开关','通电观察导体棒运动。|仅反转电流方向重复。|仅调换磁极后再比较。','只改变电流或磁场方向，受力方向反向；同时反转二者，受力方向不变。','磁场对通电导体有力的作用，方向同时与电流和磁场有关。','控制变量判断方向关系|这是电动机原理，不是电磁感应','导线不通电时不能套用同样的受力结论','同时反转电流与磁场，受力是否反向？','不会，两次反向作用抵消，受力方向保持不变。',safety='使用限流电源，防止裸导体短路和发热。')
add('coil-torque','20.4','162–163','演示实验','通电线圈为什么不能自行连续转动','magnet','coil','比较线圈不同角度时的受力效果。','矩形线圈模型|磁体|直流电源','把线圈置于不同初始角度。|通电观察转动趋势。|比较越过平衡位置前后的力矩。','线圈趋向平衡位置；未经换向的直流线圈不能持续同向转动。','要维持同向转动，需要在适当位置改变线圈中的电流方向。','平衡位置受力可能不为零，但转动效果为零','不能把平衡位置解释成没有磁场','线圈越过平衡位置后为何可能转回？','电流方向未改变，磁力矩转为阻碍原转动方向，使线圈返回平衡附近。')
add('dc-motor-project','20.5','165–166','拓展探究','制作简易直流电动机模型','magnet','motor','联系线圈受力、惯性和换向实现持续转动。','漆包线圈|磁体|低压电池|支架|换向部件模型','设计转子和定子位置。|理解半周供电或换向方式。|调节磁场和接触条件，观察持续转动。','适当换向或间歇供电配合惯性可以维持转动。','电动机将电能转化为机械能，换向保证合适的转动方向。','简易半刮漆结构与完整换向器的作用方式应区分','转得快不等于能量转换效率一定高','电动机正常工作时发生什么能量转化？','主要把电能转化为机械能，同时有电阻发热等损耗。',safety='不得长时间堵转；断电后再调整线圈和支架。')
add('electromagnetic-induction','20.6','167–168','学生实验','探究产生感应电流的条件','induction','wire','通过导体运动、回路通断和磁场方向判断感应电流。','蹄形磁体|导体棒|灵敏电流表|导线','将导体棒与电流表组成闭合回路。|分别静止、平行或横切磁感线运动。|反向运动、换磁极和断开回路进行对照。','闭合回路的一部分导体切割磁感线时可出现电流；方向随运动或磁场反向而改变。','感应电流需要合适的磁通变化和闭合电路；初中以切割磁感线条件描述。','无电源也可产生感应电流|闭合条件不可漏写','有磁场不等于一定有感应电流','导体在磁场里静止，电流表会持续偏转吗？','在磁场稳定的本实验中不会，因为没有产生持续感应电流所需的变化。')
add('hand-generator','20.6','169','演示实验','手摇发电机与交替发光的LED','induction','generator','通过摇动和电流方向变化认识发电机。','手摇发电机|小灯泡|反向并联LED|电流表示意','缓慢转动摇把并观察灯泡。|改变转速比较输出。|用反向并联LED观察电流方向交替。','转速改变时亮度变化；两个LED可交替发光。','发电机将机械能转化为电能，常见交流发电机输出电流方向周期改变。','方向周期变化是交流特征|能量来自外力做功','发电机并非制造或储存电荷','为什么要把两只LED反向并联？','它们分别在相反方向电流流过时导通，便于观察电流方向交替。')
